import {SqliteAgentTokenBudget,AgentBudgetRecovery,createBudgetHttpsVerifier} from '../../dist/index.js';
const [path,url]=process.argv.slice(2),scope={tenantId:'tenant',agentId:'agent'},target={scope,runId:'run',maxTokens:100},budget=new SqliteAgentTokenBudget(path,{scope,runId:'run',leaseToken:'retired-token',maxTokens:100,cost:{currency:'USD',maxMicros:1000},clock:()=>110});
try{const verify=createBudgetHttpsVerifier({target,url,bearerToken:'a'.repeat(32),timeoutMs:5000,maxPending:1,interpret:(body,context)=>body&&body.found===true&&body.callId===context.callId&&body.currency===context.cost?.currency?{usedTokens:body.usedTokens,usedCostMicros:body.usedCostMicros}:undefined}),recovery=new AgentBudgetRecovery({budget,target,authorize:actor=>actor.principalId==='operator',verify});const outcome=await recovery.reconcile({tenantId:'tenant',principalId:'operator'},'call','provider-case');process.send?.({outcome,call:budget.get('call'),cost:budget.getCost('call'),evidence:budget.reconciliationHistory()});}catch(error){process.send?.({error:String(error)});process.exitCode=1;}finally{budget.close();}
